  query('*') // Validate all query parameters
    .custom((value, { req, path }) => {
      // Sanitize against dangerous characters that could indicate injection
      const dangerousChars = ["'", "\"", ";", "--", "/*", "*/", /*", "OR", "UNION", "SELECT"];

