const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class ProductionSecrets {
  constructor() {
    this.secretsCache = new Map();
    this.secretsManager = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1'
    });
  }

  async getSecret(secretName) {
    // Check cache first
    if (this.secretsCache.has(secretName)) {
      return this.secretsCache.get(secretName);
    }

    try {
      const data = await this.secretsManager.send(
        new GetSecretValueCommand({ SecretId: secretName })
      );

      let secret;
      if (data.SecretString) {
        secret = JSON.parse(data.SecretString);
      } else {
        const buff = Buffer.from(data.SecretBinary, 'base64');
        secret = JSON.parse(buff.toString('utf8'));
      }

      // Cache the secret (with TTL if supported by secrets manager)
      this.secretsCache.set(secretName, secret);
      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error);
      throw error;
    }
