// config/secrets.js
const fs = require('fs');
const path = require('path');

// List of required secrets
const REQUIRED_SECRETS = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID', 
  'AWS_SECRET_ACCESS_KEY',
  // Add other required secrets here
];

// List of optional secrets
const OPTIONAL_SECRETS = [
  'LOGFIRE_TOKEN',
  'OPENAI_API_KEY'
];

function loadSecrets() {
  const envPath = process.env.SECRETS_PATH || path.join(__dirname, '..', '.env.test');

  // Load .env file if it exists
  if (fs.existsSync(envPath)) {
    console.log(`Loading secrets from: ${envPath}`);
    const envContent = fs.readFileSync(envPath, 'utf8');

    // Check file permissions (should be 600)
    const stats = fs.statSync(envPath);
    const octalPerms = stats.mode.toString(8);
    if (octalPerms !== '600' && octalPerms !== '644') {
      console.warn('⚠️  Secret file permissions are not restrictive enough');
    }

    for (const line of envContent.split('\n')) {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('#')) {
        const [key, ...valueParts] = trimmed.split('=');
        const value = valueParts.join('=');
        if (!process.env[key]) { // Give priority to existing env vars
          process.env[key] = value;
        }
      }
    }
  }

  // Validate required secrets
  const missingSecrets = REQUIRED_SECRETS.filter(key => !process.env[key]);
  if (missingSecrets.length > 0) {
    console.error('Missing required secrets:', missingSecrets.join(', '));
    process.exit(1);
