### 5. **CSP with unsafe-inline**

**Issue:** The Content Security Policy (CSP) includes `'unsafe-inline'` in styleSrc, which reduces protection against XSS attacks.

**OWASP Top 10 Alignment:** A03:2021 - Injection

**Recommendation:**
```javascript
// Remove 'unsafe-inline' and use nonce-based CSP
contentSecurityPolicy: {
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'nonce-{{cspNonce}}'"], // Use nonces instead
    imgSrc: ["'self'", "data:", "https:"],
    connectSrc: ["'self'"],
    fontSrc: ["'self'"],
    objectSrc: ["'none'"],
    frameAncestors: ["'none'"],
  },
},
// Then in your response middleware
app.use((req, res, next) => {
  res.locals.cspNonce = crypto.randomUUID();
  res.setHeader('Content-Security-Policy', res.getHeader('Content-Security-Policy')
    .replace("{{cspNonce}}", res.locals.cspNonce));
  next();
});
```

### 6. **Missing CORS Configuration**

**Issue:** While the CSP is configured, there's no explicit CORS configuration, which could lead to unexpected cross-origin requests.

**OWASP Top 10 Alignment:** A01:2021 - Broken Access Control

**Recommendation:**
```javascript
const cors = require('cors');

// Explicit CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS 
    ? process.env.ALLOWED_ORIGINS.split(',') 
    : ['https://yourdomain.com'],
  methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
}));
```

### 7. **Missing HTTP-only Cookies**

**Issue:** The application appears to rely on token-based authentication without secure cookie handling.

**Recommendation:**
```javascript
// For session-based authentication
app.use(require('cookie-parser')());

// Set HTTP-only cookies for tokens
app.post('/login', (req, res) => {
  const token = jwt.sign({ userId: user.id }, JWT_SECRET);
  res.cookie('token', token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict',
    maxAge: 24 * 60 * 60 * 1000, // 24 hours
  });
  res.json({ message: 'Login successful' });
});
```

### 8. **Insecure Error Handling**

**Issue:** The error handler doesn't properly sanitized error messages for production environments.

**OWASP Top 10 Alignment:** A05:2021 - Security Misconfiguration

**Recommendation:**
```javascript
// Improve error handling
const errorHandler = (err, req, res, next) => {
  // Log error details internally
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV !== 'production' ? err.stack : undefined,
    type: err.constructor.name,
  });

  // Don't expose internal errors
  const statusCode = err.status || err.statusCode || 500;

  // For production, avoid exposing error details
  const errorResponse = {
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : err.message || 'Internal server error',
  };

  // Add request tracking for debugging
  if (process.env.NODE_ENV !== 'production') {
    errorResponse.requestId = req.id;
  }

  res.status(statusCode).json(errorResponse);
};
```

### 9. **Missing Security Logging**

**Issue:** The application lacks comprehensive security event logging (failed logins, access attempts, etc.).

**Recommendation:**
```javascript
const morgan = require('morgan');

// Custom log format with security information
const logFormat = process.env.NODE_ENV === 'production' 
  ? 'combined' 
  : 'dev';

app.use(morgan(logFormat, {
