/**
 * Secrets Manager
 * 
 * Securely manages application secrets with support for multiple sources:
 * - Environment variables (highest priority)
 * - AWS Secrets Manager (production)
 * - Azure Key Vault (production)
 * - GCP Secret Manager (production)
 * - Local .env files (development only)
 * 
 * Security Features:
 * - Secrets are redacted in logs
 * - Automatic validation of required secrets
 * - Graceful degradation if optional secrets are missing
 * - Secret rotation notifications
 */

const fs = require('fs');
const path = require('path');

// Configuration
const CONFIG = {
  envFile: process.env.ENV_FILE || '.env.test',
  requiredSecrets: [
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID', 
    'AWS_SECRET_ACCESS_KEY'
  ],
  optionalSecrets: [
    'ANTHROPIC_API_KEY',
    'STRIPE_SECRET_KEY', 
    'LOGFIRE_TOKEN',
    'OPENAI_API_KEY'
  ],
  canaryPatterns: [
    'CANARY',
    'test',
    'dummy',
    'placeholder',
    'example',
    'fake',
    'invalid'
  ]
};

/**
 * Redact sensitive values for logging
 * @param {string} value - The value to redact
 * @param {number} visibleChars - Number of characters to show at start/end
 * @returns {string} Redacted value
 */
function redactValue(value, visibleChars = 4) {
  if (!value || value.length < visibleChars * 2) {
    return '***[REDACTED]***';
  }
  return `${value.substring(0, visibleChars)}...${value.substring(value.length - visibleChars)}`;
}

/**
 * Check if a value appears to be a test/canary value
 * @param {string} value - Value to check
 * @returns {boolean} Is this a canary value
 */
function isCanaryValue(value) {
  if (!value) return false;
  const lowerValue = value.toLowerCase();
  return CONFIG.canaryPatterns.some(pattern => 
    lowerValue.includes(pattern.toLowerCase())
  );
}

/**
 * Parse .env file content
 * @param {string} content - .env file content
 * @returns {object} Parsed environment variables
 */
function parseEnvFile(content) {
  const envVars = {};
  const lines = content.split(/\r?\n/);

  for (const line of lines) {
    const trimmed = line.trim();

    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex < 0) continue;

    const key = trimmed.slice(0, eqIndex).trim();
    const value = trimmed.slice(eqIndex + 1).trim();

    if (key) {
      envVars[key] = value;
    }
  }

  return envVars;
}

/**
 * Load secrets from .env file (development only)
 * @param {string} envPath - Path to .env file
 * @returns {object} Loaded environment variables
 */
async function loadFromEnvFile(envPath) {
  try {
    if (!fs.existsSync(envPath)) {
      return {};
    }

    const content = fs.readFileSync(envPath, 'utf8');
    return parseEnvFile(content);
  } catch (error) {
    console.warn(`[SECURITY] Failed to load secrets from ${envPath}: ${error.message}`);
    return {};
  }
}

/**
 * Load secrets from AWS Secrets Manager
 * @returns {Promise<object>} Secrets from AWS
 */
async function loadFromAwsSecretsManager() {
  try {
    // This would require AWS SDK to be installed
    // const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

    console.log('[SECURITY] AWS Secrets Manager integration not implemented');
    return {};
  } catch (error) {
    console.error('[SECURITY] AWS Secrets Manager error:', error.message);
    return {};
  }
}

/**
 * Load secrets from Azure Key Vault
 * @returns {Promise<object>} Secrets from Azure
 */
async function loadFromAzureKeyVault() {
  console.log('[SECURITY] Azure Key Vault integration not implemented');
  return {};
}

/**
 * Load secrets from GCP Secret Manager
 * @returns {Promise<object>} Secrets from GCP
 */
async function loadFromGcpSecretManager() {
  console.log('[SECURITY] GCP Secret Manager integration not implemented');
  return {};
}

/**
 * Validate loaded secrets
 * @param {object} loadedSecrets - The loaded secrets to validate
 * @returns {object} Validation results
 */
function validateSecrets(loadedSecrets) {
  const results = {
    valid: true,
    missing: [],
    canary: [],
    warnings: []
  };

  // Check required secrets
  for (const secret of CONFIG.requiredSecrets) {
    if (!loadedSecrets[secret]) {
      results.valid = false;
      results.missing.push(secret);
      results.warnings.push(`[CRITICAL] Required secret missing: ${secret}`);
    } else if (isCanaryValue(loadedSecrets[secret])) {
      results.canary.push(secret);
      results.warnings.push(`[WARNING] Required secret appears to be canary: ${secret}`);
    }
  }

  // Check optional secrets
  for (const secret of CONFIG.optionalSecrets) {
    if (loadedSecrets[secret] && isCanaryValue(loadedSecrets[secret])) {
      results.canary.push(secret);
      results.warnings.push(`[INFO] Optional secret contains canary value: ${secret}`);
    }
  }

  return results;
}

/**
 * Load all secrets
 * @returns {Promise<object>} All loaded secrets
 */
async function loadAllSecrets() {
  console.log('[SECURITY] Loading secrets...');

  const secrets = {};
  const envFileSeverity = process.env.NODE_ENV === 'production' ? 'error' : 'warn';

  // Development: Load from .env file if no environment variables set
  if (process.env.NODE_ENV !== 'production' && 
      Object.keys(process.env).filter(k => CONFIG.requiredSecrets.includes(k)).length === 0) {

    console.log(`[${envFileSeverity.toUpperCase()}] Loading secrets from ${CONFIG.envFile} (development mode)`);
    const envFileSecrets = await loadFromEnvFile(path.join(__dirname, CONFIG.envFile));
    Object.assign(secrets, envFileSecrets);
  }

  // Always load from environment variables (highest priority)
  CONFIG.requiredSecrets.forEach(secret => {
    if (process.env[secret]) {
      secrets[secret] = process.env[secret];
    }
  });

  CONFIG.optionalSecrets.forEach(secret => {
    if (process.env[secret]) {
      secrets[secret] = process.env[secret];
    }
  });

  // Validation
  const validation = validateSecrets(secrets);

  if (!validation.valid) {
    console.error('[SECURITY] Secret validation failed:');
    validation.warnings.forEach(warning => console.error(warning));
  } else if (validation.canary.length > 0) {
    console.warn('[SECURITY] Canary values detected - verify this is intentional for development:');
    validation.canary.forEach(secret => console.warn(`  - ${redactValue(secrets[secret])}`));
  } else {
    console.log('[SECURITY] Secrets loaded successfully');
  }

  return {
    ...secrets,
    // Helper methods
    get(secretName) {
      return secrets[secretName];
    },

    getAll() {
      // Return redacted copy for logging
      const redacted = {};
      for (const [key, value] of Object.entries(secrets)) {
        redacted[key] = redactValue(value);
      }
      return redacted;
    },

    isCanary(secretName) {
      return isCanaryValue(secrets[secretName]);
    },

    /**
     * Log secrets safely
     */
    log() {
      console.log('[SECURITY] Current secret configuration:');
      for (const secret of [...CONFIG.requiredSecrets, ...CONFIG.optionalSecrets]) {
        if (secrets[secret]) {
          console.log(`  ${secret}: ${redactValue(secrets[secret])}`);
        }
      }
    }
  };
}

/**
 * Initialize secrets manager
 * @returns {Promise<object>} Initialized secrets object
 */
async function initializeSecrets() {
  const secrets = await loadAllSecrets();

  // Store secrets in process for backward compatibility
  Object.assign(process.env, secrets);

  return secrets;
}

// Export the module
module.exports = {
  initializeSecrets,
  redactValue,
  isCanaryValue,
  validateSecrets,
  loadAllSecrets
};

// Auto-initialize if run directly
if (require.main === module) {
  initializeSecrets()
    .then(() => {
      console.log('\n[SECURITY] Secrets initialized successfully');
      process.exit(0);
    })
