/**
 * Secrets Management Module
 * Handles loading and validation of application secrets
 * Supports multiple secret loading strategies:
 * - .env files (development)
 * - AWS Secrets Manager (production)
 * - Azure Key Vault (production)
 * - Google Secret Manager (production)
 */

require('dotenv').config();

// Load environment-specific configuration
const loadSecrets = () => {
  const secrets = {
    // Application secrets
    NODE_ENV: process.env.NODE_ENV || 'development',

    // Authentication secrets (CRITICAL - MUST BE SET)
    JWT_SECRET: getSecret('JWT_SECRET', 'Please set JWT_SECRET environment variable'),
    JWT_EXPIRY: process.env.JWT_EXPIRY || '24h',

    // Session secrets
    SESSION_SECRET: getSecret('SESSION_SECRET', 'Please set SESSION_SECRET environment variable'),
    SESSION_DURATION: process.env.SESSION_DURATION || '86400000', // 24 hours in milliseconds

    // Database configuration
    DATABASE_URL: getSecret('DATABASE_URL', 'Please set DATABASE_URL environment variable'),

    // External API secrets
    STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY || null,
    STRIPE_WEBHOOK_SECRET: process.env.STRIPE_WEBHOOK_SECRET || null,

    // Cloud provider secrets (if applicable)
    AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY || null,
    AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID || null,

    // Third-party services
    ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY || null,

    // Logging and monitoring
    LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN || null,
  };

  // Validate critical secrets
  validateSecrets(secrets);

  return secrets;
};

/**
 * Get secret from environment or throw error
 */
const getSecret = (key, errorMessage) => {
  const value = process.env[key];

  if (!value) {
    console.error(`❌ ${errorMessage}`);
    process.exit(1);
  }

  return value;
};

/**
 * Validate secrets for security issues
 */
const validateSecrets = (secrets) => {
  const canaryIndicators = [
    'CANARY', 'test', 'dummy', 'placeholder', 
    'example', 'fake', 'invalid', 'bad'
  ];

  const secretKeys = Object.keys(secrets);

  for (const key of secretKeys) {
    const value = secrets[key];

    if (value && typeof value === 'string') {
      const lowerValue = value.toLowerCase();

      // Check for canary/test values (except in development/testing environments)
      if (secrets.NODE_ENV === 'production') {
        for (const indicator of canaryIndicators) {
          if (lowerValue.includes(indicator)) {
            console.error(`❌ Security Alert: ${key} contains canary/test indicator: ${indicator}`);
            console.error('   This should not happen in production!');
            process.exit(1);
          }
        }
      }

      // Check for missing or empty secrets
      if (!value.trim()) {
        console.error(`❌ Security Alert: ${key} is empty or whitespace`);
        process.exit(1);
      }
    }
  }

  console.log('✅ Secrets validated successfully');
};

/**
 * Get secrets from AWS Secrets Manager (advanced)
 */
const getAWSSecrets = async (secretName) => {
  try {
    const AWS = require('aws-sdk');

    // Check if running in AWS environment
    if (process.env.AWS_SECRET_ACCESS_KEY && process.env.AWS_ACCESS_KEY_ID) {
      const secretsManager = new AWS.SecretsManager();

      try {
        const data = await secretsManager.getSecretValue({ SecretId: secretName }).promise();
        return JSON.parse(data.SecretString);
      } catch (error) {
        console.error('❌ Failed to get secrets from AWS Secrets Manager:', error);
        return null;
      }
    }

    return null;
  } catch (error) {
    console.warn('⚠️  AWS SDK not available or not running in AWS:');
    console.warn('   ', error.message);
    return null;
  }
};

/**
 * Get secrets from Azure Key Vault (advanced)
 */
const getAzureSecrets = async (vaultName) => {
  // Azure Key Vault implementation would go here
  console.warn('⚠️  Azure Key Vault integration not implemented');
  return null;
};

/**
 * Get secrets from Google Secret Manager (advanced)
 */
const getGoogleSecrets = async (projectId, secretName) => {
  // Google Secret Manager implementation would go here
  console.warn('⚠️  Google Secret Manager integration not implemented');
  return null;
};

module.exports = {
  loadSecrets,
  getAWSSecrets,
  getAzureSecrets,
  getGoogleSecrets,
  validateSecrets,
};

